ALTER TABLE visitor_observations ADD CONSTRAINT visitor_observations_scope UNIQUE (organization_id, business_id, visitor_identity_id, id);
ALTER TABLE visitor_observations DROP CONSTRAINT IF EXISTS visitor_observations_correction_of_observation_id_fkey;
ALTER TABLE visitor_observations ADD CONSTRAINT visitor_observations_correction_scope_fkey FOREIGN KEY (organization_id, business_id, visitor_identity_id, correction_of_observation_id) REFERENCES visitor_observations (organization_id, business_id, visitor_identity_id, id) ON DELETE CASCADE;
CREATE OR REPLACE FUNCTION kablet_visitor_privacy_delete(p_organization_id uuid, p_visitor_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$ DECLARE deleted boolean; BEGIN IF p_organization_id <> public.kablet_current_org() THEN RAISE EXCEPTION 'privacy tenant mismatch'; END IF; DELETE FROM public.visitor_states WHERE organization_id = p_organization_id AND visitor_identity_id = p_visitor_id; DELETE FROM public.visitor_observations WHERE organization_id = p_organization_id AND visitor_identity_id = p_visitor_id; DELETE FROM public.visitor_state_revisions WHERE organization_id = p_organization_id AND visitor_identity_id = p_visitor_id; DELETE FROM public.visitor_sessions WHERE organization_id = p_organization_id AND visitor_identity_id = p_visitor_id; DELETE FROM public.visitor_identities WHERE organization_id = p_organization_id AND id = p_visitor_id RETURNING true INTO deleted; RETURN COALESCE(deleted, false); END $$;
